import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.position.set(0, 0, 0);
  root.rotation.set(0, 0, 0);
  root.scale.set(1, 1, 1);

  const PANEL_W = 3.2;
  const PANEL_H = 2.2;

  // ===== Panel Background with Gradient and Grid =====
  const bgCanvas = document.createElement('canvas');
  bgCanvas.width = 512;
  bgCanvas.height = 320;
  const bgCtx = bgCanvas.getContext('2d');

  // Radial gradient
  const cx = bgCanvas.width / 2;
  const cy = bgCanvas.height / 2;
  const maxR = Math.max(bgCanvas.width, bgCanvas.height);
  const radGrad = bgCtx.createRadialGradient(cx, cy, 0, cx, cy, maxR);
  radGrad.addColorStop(0, '#14141a');
  radGrad.addColorStop(1, '#0b0b10');
  bgCtx.fillStyle = radGrad;
  bgCtx.fillRect(0, 0, bgCanvas.width, bgCanvas.height);

  // Grid overlay
  bgCtx.strokeStyle = '#e8ecf2';
  bgCtx.globalAlpha = 0.06;
  bgCtx.lineWidth = 1;
  const gridPitch = 16;
  for (let x = 0; x <= bgCanvas.width; x += gridPitch) {
    bgCtx.beginPath();
    bgCtx.moveTo(x, 0);
    bgCtx.lineTo(x, bgCanvas.height);
    bgCtx.stroke();
  }
  for (let y = 0; y <= bgCanvas.height; y += gridPitch) {
    bgCtx.beginPath();
    bgCtx.moveTo(0, y);
    bgCtx.lineTo(bgCanvas.width, y);
    bgCtx.stroke();
  }

  // Hairline border
  bgCtx.globalAlpha = 1;
  bgCtx.strokeStyle = '#26262f';
  bgCtx.lineWidth = 1;
  const br = 10;
  bgCtx.beginPath();
  bgCtx.moveTo(br, 0);
  bgCtx.arcTo(bgCanvas.width, 0, bgCanvas.width, br, br);
  bgCtx.lineTo(bgCanvas.width, bgCanvas.height - br);
  bgCtx.arcTo(bgCanvas.width, bgCanvas.height, bgCanvas.width - br, bgCanvas.height, br);
  bgCtx.lineTo(br, bgCanvas.height);
  bgCtx.arcTo(0, bgCanvas.height, 0, bgCanvas.height - br, br);
  bgCtx.lineTo(0, br);
  bgCtx.arcTo(0, 0, br, 0, br);
  bgCtx.closePath();
  bgCtx.stroke();

  const bgTex = new THREE.CanvasTexture(bgCanvas);
  bgTex.magFilter = THREE.LinearFilter;
  bgTex.minFilter = THREE.LinearFilter;

  const panelGeo = new THREE.PlaneGeometry(PANEL_W, PANEL_H);
  const panelMat = new THREE.MeshBasicMaterial({ map: bgTex, transparent: true });
  const panelMesh = new THREE.Mesh(panelGeo, panelMat);
  panelMesh.position.z = 0;
  root.add(panelMesh);

  // ===== Ghost Preview (Wireframe Watch Card) =====
  const ghostGroup = new THREE.Group();
  ghostGroup.position.set(-0.6, 0.15, 0.01);

  // Watch card outline
  const ww = 1.1, wh = 1.4;
  const watchCardPts = [
    new THREE.Vector3(-ww / 2, -wh / 2, 0),
    new THREE.Vector3(ww / 2, -wh / 2, 0),
    new THREE.Vector3(ww / 2, wh / 2, 0),
    new THREE.Vector3(-ww / 2, wh / 2, 0),
    new THREE.Vector3(-ww / 2, -wh / 2, 0),
  ];
  const watchCardGeo = new THREE.BufferGeometry().setFromPoints(watchCardPts);
  const ghostStrokeMat = new THREE.LineBasicMaterial({
    color: 0xe8ecf2,
    transparent: true,
    opacity: 0.3,
  });
  const watchCardLine = new THREE.Line(watchCardGeo, ghostStrokeMat);
  ghostGroup.add(watchCardLine);

  // Dial circle
  const dialGeo = new THREE.CircleGeometry(0.275, 32);
  const dialLine = new THREE.LineLoop(dialGeo, ghostStrokeMat);
  ghostGroup.add(dialLine);

  // Ghost text bars
  const ghostBarMat = new THREE.LineBasicMaterial({
    color: 0xe8ecf2,
    transparent: true,
    opacity: 0.22,
  });

  const bw = 0.7, bh = 0.06;
  [0.4, 0.25].forEach((barY) => {
    const barPts = [
      new THREE.Vector3(-bw / 2, -bh / 2, 0),
      new THREE.Vector3(bw / 2, -bh / 2, 0),
      new THREE.Vector3(bw / 2, bh / 2, 0),
      new THREE.Vector3(-bw / 2, bh / 2, 0),
    ];
    const barGeo = new THREE.BufferGeometry().setFromPoints(barPts);
    const bar = new THREE.LineLoop(barGeo, ghostBarMat);
    bar.position.y = barY;
    ghostGroup.add(bar);
  });

  // Ghost breathing animation
  gsap.timeline({ repeat: -1, yoyo: true })
    .to({ v: 0 }, {
      v: 1,
      duration: 2.4,
      ease: 'cubic-bezier(0.445, 0.05, 0.55, 0.95)',
      onUpdate(tween) {
        const progress = tween.targets()[0].v;
        const opacity = 0.24 + (0.34 - 0.24) * progress;
        ghostStrokeMat.opacity = opacity / 0.24 * 0.3;
        ghostBarMat.opacity = opacity / 0.24 * 0.22;
      },
    }, 0);

  root.add(ghostGroup);

  // ===== Text Content =====
  const headline = ctx.fontAtlas.createText({
    text: "Your ledger is empty.",
    fontSize: 34,
    fontWeight: 600,
    family: "Lora",
    color: '#e8ecf2',
  });
  headline.position.set(0.2, 0.5, 0.02);
  root.add(headline);

  const body = ctx.fontAtlas.createText({
    text: "Commissioned pieces and\nsaved references will appear\nhere once you begin.",
    fontSize: 13,
    fontWeight: 400,
    family: "JetBrains Mono",
    color: '#e8ecf2',
  });
  body.position.set(0.2, 0, 0.02);
  root.add(body);

  // ===== CTA Button =====
  const ctaCanvas = document.createElement('canvas');
  ctaCanvas.width = 240;
  ctaCanvas.height = 72;
  const ctaCtx = ctaCanvas.getContext('2d');

  // Gradient background
  const ctaGrad = ctaCtx.createLinearGradient(0, 0, 0, ctaCanvas.height);
  ctaGrad.addColorStop(0, '#ff4450');
  ctaGrad.addColorStop(1, '#c1121f');
  ctaCtx.fillStyle = ctaGrad;
  ctaCtx.fillRect(0, 0, ctaCanvas.width, ctaCanvas.height);

  // Rounded border
  ctaCtx.strokeStyle = '#ff2a38';
  ctaCtx.lineWidth = 2;
  const ctaBr = 8;
  ctaCtx.beginPath();
  ctaCtx.moveTo(ctaBr, 0);
  ctaCtx.arcTo(ctaCanvas.width, 0, ctaCanvas.width, ctaBr, ctaBr);
  ctaCtx.lineTo(ctaCanvas.width, ctaCanvas.height - ctaBr);
  ctaCtx.arcTo(ctaCanvas.width, ctaCanvas.height, ctaCanvas.width - ctaBr, ctaCanvas.height, ctaBr);
  ctaCtx.lineTo(ctaBr, ctaCanvas.height);
  ctaCtx.arcTo(0, ctaCanvas.height, 0, ctaCanvas.height - ctaBr, ctaBr);
  ctaCtx.lineTo(0, ctaBr);
  ctaCtx.arcTo(0, 0, ctaBr, 0, ctaBr);
  ctaCtx.closePath();
  ctaCtx.stroke();

  const ctaTex = new THREE.CanvasTexture(ctaCanvas);
  ctaTex.magFilter = THREE.LinearFilter;
  ctaTex.minFilter = THREE.LinearFilter;

  const ctaGeo = new THREE.PlaneGeometry(1.5, 0.36);
  const ctaMat = new THREE.MeshBasicMaterial({ map: ctaTex, transparent: true });
  const ctaButton = new THREE.Mesh(ctaGeo, ctaMat);
  ctaButton.position.set(0.2, -0.75, 0.02);
  root.add(ctaButton);

  // CTA label
  const ctaLabel = ctx.fontAtlas.createText({
    text: "BROWSE THE COLLECTION",
    fontSize: 13,
    fontWeight: 700,
    family: "JetBrains Mono",
    color: '#16161d',
    letterSpacing: 0.08,
  });
  ctaLabel.position.set(0.2, -0.75, 0.03);
  root.add(ctaLabel);

  // ===== Event Handlers =====
  root.userData.handlers = {
    onCTAPress: () => {
      gsap.to(ctaButton.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
    },
    onCTARelease: () => {
      gsap.to(ctaButton.scale, {
        x: 1,
        y: 1,
        duration: 0.12,
        ease: 'back.out',
      });
    },
  };

  // ===== Mount Animation =====
  root.position.y = 0.2;
  panelMat.opacity = 0;
  ctaMat.opacity = 0;

  gsap.to([panelMat, ctaMat], {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  });

  gsap.to(root.position, {
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
  });

  // ===== Cleanup =====
  root.userData.cleanup = () => {
    gsap.killTweensOf([root, root.position, ctaButton, ctaButton.scale, panelMat, ctaMat]);

    bgTex.dispose();
    panelMat.dispose();
    panelGeo.dispose();
    ctaTex.dispose();
    ctaMat.dispose();
    ctaGeo.dispose();
    ghostStrokeMat.dispose();
    ghostBarMat.dispose();
    watchCardGeo.dispose();
    dialGeo.dispose();

    bgCanvas.remove();
    ctaCanvas.remove();
  };

  return root;
}
